// BestTV вэб чат — { sessionId, message, name } задална → AI Agent-д өгнө.
const body = $input.first().json.body || {};
const sessionId = String(body.sessionId || 'web_anon').slice(0, 64);
const userText = String(body.message || '').trim();
const name = (body.name || '').trim();

if (!userText) {
  return [{ json: { psid: sessionId, userText: '', agentInput: '', empty: true } }];
}

const NL = String.fromCharCode(10);
const nameLine = name ? ('Хэрэглэгчийн нэр: ' + name) : '';
const agentInput = [nameLine, '=== ХЭРЭГЛЭГЧИЙН МЕССЕЖ ===', userText].filter(Boolean).join(NL);

return [{ json: { psid: sessionId, userText, agentInput } }];

// AI хариунаас [SEARCH:keyword] салгаж, цэвэр текст бэлдэнэ.
const prep = $('Prep').first().json;
const psid = prep.psid;
let raw = ($input.first().json.output || '').trim();

let keyword = '';
const m = raw.match(/\[SEARCH:\s*([^\]]*)\]/i);
if (m) { keyword = (m[1] || '').trim(); }

// Тэмдгийг хэрэглэгчид харагдах текстээс бүрэн арилгана
let replyText = raw.replace(/\[SEARCH:[^\]]*\]/ig, '').trim();

// Markdown цэвэрлэх: [текст](url) → "текст url", ** __ устгах
function stripMd(s){ s=String(s||''); var r='',i=0; while(i<s.length){ if(s[i]==='['){ var c=s.indexOf('](',i); if(c!==-1){ var e=s.indexOf(')',c+2); if(e!==-1){ var t=s.slice(i+1,c).trim(); var u=s.slice(c+2,e).trim(); r+=(t===u||!t)?u:(t+' '+u); i=e+1; continue; } } } r+=s[i]; i++; } r=r.split('**').join('').split('__').join(''); return r.trim(); }
replyText = stripMd(replyText);

// ⚠️ FAQ ХАМГААЛАЛТ: AI ерөнхий асуултыг андуурч [SEARCH:]-д тавьсан бол хайхгүй.
// Эс бөгөөс "яаж төлөх вэ" гэсэнд кино хайж "олдсонгүй" гэж хариулна.
const kwLc = keyword.toLowerCase().replace(/\s+/g, ' ').trim();
const FAQ_STOP = ['багц','үнэ','төлбөр','тулбур','qpay','купон','хэтэвч','буцаалт','эрх',
  'хэрхэн','яаж','нэвтрэх','бүртгэл','бүртгүүлэх','нууц үг','имэйл','тусламж',
  'холбоо барих','админ','vip','цэнэглэх','захиалга','үзэх заавар','заавар'];
for (let i = 0; i < FAQ_STOP.length; i++) { if (kwLc === FAQ_STOP[i]) { keyword = ''; break; } }


// ⚠️ FALLBACK: gpt-4o-mini нь [SEARCH:] заавраа тогтмол дагадаггүй тул
// AI тэмдэг өгөөгүй үед ХЭРЭГЛЭГЧИЙН мессежээс кодоор түлхүүр үг олно.
// (DigitalGer-ийн contact-trigger хэв маягтай ижил — AI-д найдахгүй.)
if (!keyword) {
  const userText = String(prep.userText || '').toLowerCase();

  // Багц/төлбөр/заавартай холбоотой бол хайлт хийхгүй
  const NO_SEARCH = ['багц','үнэ','төлбөр','төлөх','qpay','купон','хэтэвч','цэнэглэ',
    'бүртгүүл','нэвтрэх','нууц үг','имэйл','яаж','хэрхэн','тусламж','холбоо',
    'сайн уу','сайн байна','баярлалаа','vip','захиалга','цуцлах','буцаалт'];
  const skip = NO_SEARCH.some((t) => userText.includes(t));

  if (!skip) {
    // Жанр/төрлийн түлхүүр үгс — киноны сэдэвтэй холбоотой эсэхийг танина
    const GENRE = [
      ['монгол', 'монгол'], ['солонгос', 'солонгос'], ['хятад', 'хятад'],
      ['орос', 'орос'], ['хайр', 'хайр'], ['инээдм', 'инээдмийн'],
      ['аймшг', 'аймшгийн'], ['адал', 'адал явдал'], ['шинэ', 'шинэ'],
      ['цуврал', 'цуврал'], ['драм', 'драм'], ['экшн', 'экшн'],
    ];
    for (let i = 0; i < GENRE.length; i++) {
      if (userText.includes(GENRE[i][0])) { keyword = GENRE[i][1]; break; }
    }
    // Жанр олдоогүй ч "кино/цуврал/үзэх" гэсэн үг байвал ерөнхий хайлт
    if (!keyword && /кино|цуврал|үзэх|үзмээр|санал болго/.test(userText)) {
      keyword = 'кино';
    }
  }
}

const doSearch = keyword.length >= 2;
if (!replyText) { replyText = doSearch ? 'Танд тохирох кино хайж байна...' : 'Уучлаарай, дахин бичнэ үү.'; }

return [{ json: { psid, keyword, doSearch, replyText } }];

// Widget-д зориулсан эцсийн JSON: { reply, titles[] } + backend-д бичих _ingest.
const ex = $('Extract Keyword').first().json;
const replyText = (ex.replyText || '').trim() || 'Уучлаарай, дахин бичнэ үү.';

let raw = [];
try {
  const s = $('Search Titles').first().json;
  // /titles/search нь массив шууд буцаана
  raw = Array.isArray(s) ? s : (Array.isArray(s && s.data) ? s.data : []);
} catch (e) { raw = []; }

const triedSearch = ex.doSearch === true;
const list = triedSearch ? raw : [];

// Эхний 6 киног widget-ийн карт болгоно
const titles = list.slice(0, 6).map(function (t) {
  return {
    id: t.id || null,
    title: t.title || '',
    slug: t.slug || '',
    posterUrl: t.posterUrl || null,
    url: t.slug ? ('https://besttv.us/movie/' + t.slug) : null,
    year: (t.year != null) ? Number(t.year) : null,
    rating: (t.rating != null) ? Number(t.rating) : null,
  };
});

return [{ json: {
  reply: replyText,
  titles: titles,
  _ingest: {
    sessionId: String(($('Prep').first().json.psid) || '').slice(0, 64),
    userText: String(($('Prep').first().json.userText) || '').trim(),
    assistantText: String(replyText || '').trim(),
    titles: titles,
  },
} }];
